// Fill these in. The Homebox key is stored in this workflow, so remove it before sharing an export.
const settings = {
  homeboxUrl: 'http://homebox:7745',
  homeboxApiKey: 'PASTE_HOMEBOX_API_KEY',            // starts with hb_ (Homebox 0.26 or later)
  searxngUrl: 'http://searxng:8080',
  notifyWebhookUrl: 'http://homeassistant:8123/api/webhook/PASTE_LONG_RANDOM_ID',
  tag: 'Network device',
  location: '',                                       // a Homebox location name; blank uses the first one
  maxNewPerRun: 10,
  maxPdfMB: 10,                                       // keep at or under Homebox's upload limit
  ignoreMacs: [],                                     // MAC addresses or prefixes, e.g. 'aa:bb:cc'
  skipSites: [],                                      // more websites never to download from
};
return [{ json: { settings, body: $input.first().json.body || {} } }];

// Shared helpers (the same block sits in each Code node that needs it).
const cfg = $('Settings').first().json.settings;
const http = (options) => this.helpers.httpRequest(options);
const trimSlash = (s) => String(s || '').trim().replace(/\/+$/, '');

// Text from a device or a website: one line, no control characters or markup brackets, limited length.
const clean = (s, max = 60) => String(s == null ? '' : s)
  .replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u2028-\u202e\u2066-\u2069<>{}]/g, ' ')
  .replace(/\s+/g, ' ').trim().slice(0, max).trim();

const hash = (s) => {
  let h = 2166136261;
  for (const c of String(s)) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619) >>> 0; }
  return h.toString(16).padStart(8, '0');
};

// Only ordinary public web addresses: a domain name (never a bare number address), normal ports, no sign-in.
const publicHost = (url) => {
  const m = /^https?:\/\/([^\/?#\\\s]+)(?:[\/?#]\S*)?$/i.exec(String(url || ''));
  if (!m || /\\/.test(url)) return '';
  const hp = /^([a-z0-9.-]+?)\.?(?::(80|443))?$/i.exec(m[1]);
  if (!hp) return '';
  const host = hp[1].toLowerCase();
  const last = host.split('.').pop();
  if (!host.includes('.') || !/^([a-z]{2,}|xn--[a-z0-9-]+)$/.test(last)) return '';
  if (/(^|\.)(local|localhost|localdomain|lan|internal|intranet|home|corp|arpa|test|invalid)$/.test(host)) return '';
  return host;
};
// Sites TorKe never downloads from (links only), plus the gray-area manual sites.
const NEVER = ['manualslib.com', 'repairclinic.com', 'charm.li', 'lemon-manuals.la', 'lemon-manuals.org.ua'];
const blocked = (host) => NEVER.concat(cfg.skipSites || [])
  .some((d) => host === d || host.endsWith('.' + d));
const usable = (url) => { const h = publicHost(url); return h && !blocked(h) ? h : ''; };

const homebox = (method, path, body) => http({
  method, url: trimSlash(cfg.homeboxUrl) + '/api/v1' + path, body, json: true,
  headers: { Authorization: 'Bearer ' + cfg.homeboxApiKey },
});

const notify = async (title, message, extra = {}) => {
  try {
    await http({ method: 'POST', url: cfg.notifyWebhookUrl, json: true,
      body: { title: clean(title, 80), message: String(message).slice(0, 600), actions: [], url: '', tag: '', ...extra } });
    return true;
  } catch (e) { return false; }
};

// Forget an offer. n8n saves the memory when a top-level key is set, so replace the list.
const forget = (itemId) => {
  const memory = $getWorkflowStaticData('global');
  const { [itemId]: gone, ...rest } = memory.offers || {};
  memory.offers = rest;
};

// Search for a PDF manual and send the phone an approval notification.
const offerManual = async (itemId, itemName, query) => {
  const memory = $getWorkflowStaticData('global');
  memory.offers = memory.offers || {};
  let found = null; let failed = '';
  try {
    const data = await http({ method: 'GET', json: true,
      url: trimSlash(cfg.searxngUrl) + '/search?format=json&q=' + encodeURIComponent(query + ' manual filetype:pdf') });
    for (const r of (data && data.results) || []) {
      const url = String((r && r.url) || '');
      if (url.length <= 600 && /\.pdf($|[?#])/i.test(url) && usable(url)) {
        found = { url, title: clean(r.title, 90) || 'PDF', host: usable(url) }; break;
      }
    }
  } catch (e) { failed = 'The search failed. Check SearXNG and that its JSON output is on.'; }
  const id = hash(found ? found.url : query + Date.now());
  delete memory.offers[itemId];
  memory.offers[itemId] = { hash: id, url: found ? found.url : '', name: itemName };
  const keys = Object.keys(memory.offers);
  for (const k of keys.slice(0, Math.max(0, keys.length - 200))) delete memory.offers[k];
  memory.offers = { ...memory.offers };  // n8n saves the memory when a top-level key is set
  const act = (verb) => 'TORKE_' + verb + '|' + itemId + '|' + id;
  const model = { action: act('MODEL'), title: 'Fix model', behavior: 'textInput',
    textInputButtonTitle: 'Search', textInputPlaceholder: 'Maker and model number' };
  const skip = { action: act('SKIP'), title: 'Skip' };
  const message = found
    ? `${itemName}\nFound: ${found.title}\nFrom: ${found.host}\nCheck that it matches your model.`
    : `${itemName}\n${failed || 'No PDF manual found.'}\nType the maker and model number to search again.`;
  return notify(found ? 'Save this manual?' : 'Manual needed', message, {
    actions: found ? [{ action: act('SAVE'), title: 'Save manual' }, model, skip] : [model, skip],
    url: found ? found.url : '', tag: 'torke-' + itemId });
};

// NetAlertX reported new devices: filter, add each to Homebox, search for its manual.
if ($('Phone reply').isExecuted) return [];

let report = $('Settings').first().json.body;
report = report && report.attachments && report.attachments[0] && report.attachments[0].text;
if (typeof report === 'string') { try { report = JSON.parse(report); } catch (e) { report = null; } }
const rows = (report && Array.isArray(report.new_devices)) ? report.new_devices : [];

const macOf = (s) => { const m = String(s || '').trim().toLowerCase().replace(/-/g, ':');
  return /^([0-9a-f]{2}:){5}[0-9a-f]{2}$/.test(m) ? m : ''; };
const real = (s) => { const t = clean(s); return /^\(?(unknown|name not found|null|none)\)?$/i.test(t) ? '' : t.replace(/^\(unknown\)\s*/i, ''); };

const wanted = []; const seen = new Set();
for (const row of rows) {
  const mac = macOf(row.eveMac || row.MAC);
  if (!mac || seen.has(mac)) continue;
  seen.add(mac);
  const first = parseInt(mac.slice(0, 2), 16);
  if (first & 3) continue;                       // randomized or locally assigned (2), or group address (1)
  if (mac === '00:00:00:00:00:00') continue;
  if ((cfg.ignoreMacs || []).some((p) => p && mac.startsWith(String(p).toLowerCase().replace(/-/g, ':')))) continue;
  wanted.push({ mac, vendor: real(row.devVendor), host: real(row.devName || row['Device name']) });
}
if (!wanted.length) return [];

let existing; let tagId; let parentId;
try {
  const rowsOf = (d) => Array.isArray(d) ? d : (d && (d.items || d.entities)) || [];
  const tags = rowsOf(await homebox('GET', '/tags'));
  const tag = tags.find((t) => String(t.name).toLowerCase() === cfg.tag.toLowerCase());
  tagId = tag ? tag.id : (await homebox('POST', '/tags', { name: cfg.tag })).id;
  existing = [];
  for (let page = 1; page <= 20; page++) {
    const got = rowsOf(await homebox('GET', `/entities?pageSize=500&page=${page}&includeArchived=true&tags=${encodeURIComponent(tagId)}`));
    existing.push(...got);
    if (got.length < 500) break;
  }
  const places = rowsOf(await homebox('GET', '/entities?isLocation=true&pageSize=200'));
  const place = places.find((p) => cfg.location && String(p.name).toLowerCase() === cfg.location.toLowerCase()) || places[0];
  parentId = place && place.id;
} catch (e) {
  await notify('New devices not saved', `Homebox couldn't be read, so ${wanted.length} new device(s) weren't added: `
    + wanted.map((d) => d.mac).join(', '));
  throw e;
}

const known = existing.map((e) => `${e.name || ''} ${e.description || ''}`.toLowerCase()).join('\n');
const fresh = wanted.filter((d) => !known.includes(d.mac));
const done = [];
for (const d of fresh.slice(0, cfg.maxNewPerRun)) {
  const guess = [d.vendor, d.host].filter(Boolean).join(' ');
  const name = clean(guess || `Network device ${d.mac}`, 120);
  let made;
  try {
    const body = { name, quantity: 1, tagIds: [tagId],
      description: `MAC ${d.mac}. Network vendor: ${d.vendor || 'unknown'}. Hostname: ${d.host || 'unknown'}. `
        + 'Added from NetAlertX; the name is a guess until the model is confirmed.' };
    if (parentId) body.parentId = parentId;
    made = await homebox('POST', '/entities', body);
    if (!made || !made.id) throw new Error('no item id');
  } catch (e) {
    await notify('New device not saved', `Homebox didn't accept ${name} (${d.mac}).`);
    continue;
  }
  const sent = await offerManual(made.id, name, guess || d.mac.slice(0, 8));
  done.push({ json: { itemId: made.id, name, mac: d.mac, notified: sent } });
}
const over = fresh.slice(cfg.maxNewPerRun);
if (over.length) {
  await notify('More new devices', `${over.length} more weren't added (limit ${cfg.maxNewPerRun} per report): `
    + over.map((d) => d.mac).join(', '));
}
return done;

