  try {
    const data = await http({ method: 'GET', json: true,
      url: trimSlash(cfg.searxngUrl) + '/search?format=json&q=' + encodeURIComponent(query + ' manual filetype:pdf') });
    for (const r of (data && data.results) || []) {
      const url = String((r && r.url) || '');
      if (url.length <= 600 && /\.pdf($|[?#])/i.test(url) && usable(url)) {
        found = { url, title: clean(r.title, 90) || 'PDF', host: usable(url) }; break;
      }
    }
  } catch (e) { failed = 'The search failed. Check SearXNG and that its JSON output is on.'; }
  const id = hash(found ? found.url : query + Date.now());
  delete memory.offers[itemId];
  memory.offers[itemId] = { hash: id, url: found ? found.url : '', name: itemName };
  const keys = Object.keys(memory.offers);
  for (const k of keys.slice(0, Math.max(0, keys.length - 200))) delete memory.offers[k];
  memory.offers = { ...memory.offers };  // n8n saves the memory when a top-level key is set
  const act = (verb) => 'TORKE_' + verb + '|' + itemId + '|' + id;
  const model = { action: act('MODEL'), title: 'Fix model', behavior: 'textInput',
    textInputButtonTitle: 'Search', textInputPlaceholder: 'Maker and model number' };
  const skip = { action: act('SKIP'), title: 'Skip' };
  const message = found
    ? `${itemName}\nFound: ${found.title}\nFrom: ${found.host}\nCheck that it matches your model.`
    : `${itemName}\n${failed || 'No PDF manual found.'}\nType the maker and model number to search again.`;
  return notify(found ? 'Save this manual?' : 'Manual needed', message, {
    actions: found ? [{ action: act('SAVE'), title: 'Save manual' }, model, skip] : [model, skip],
    url: found ? found.url : '', tag: 'torke-' + itemId });
};

// A button press from the phone: save the manual, search again with a typed model, or skip.
if (!$('Phone reply').isExecuted) return [];
const body = $('Settings').first().json.body || {};
const m = /^TORKE_(SAVE|MODEL|SKIP)\|([A-Za-z0-9-]{1,64})\|([0-9a-f]{8})$/.exec(String(body.action || ''));
if (!m) return [];
const [, verb, itemId, id] = m;
const memory = $getWorkflowStaticData('global');
const offer = memory.offers && memory.offers[itemId];
if (!offer || offer.hash !== id) {
  await notify('Out of date', 'That notification is old or already handled. Nothing was changed.');
  return [];
}
if (verb === 'SKIP') { forget(itemId); return []; }

if (verb === 'MODEL') {
  const typed = clean(body.reply_text, 100);
  if (!typed) { await notify('No model typed', 'Nothing was changed.'); return []; }
  try {
    const full = await homebox('GET', '/entities/' + itemId);
    const tagged = (full.tags || []).some((t) => String(t.name).toLowerCase() === cfg.tag.toLowerCase());
    if (!tagged) throw new Error('not tagged');
    // Homebox's update replaces the whole item, so send back everything that was read.
    const drop = ['attachments', 'createdAt', 'updatedAt', 'parent', 'location', 'tags', 'labels', 'children',
      'entityType', 'imageId', 'thumbnailId', 'maintenance'];
    const next = Object.fromEntries(Object.entries(full).filter(([k]) => !drop.includes(k)));
    next.name = typed; next.modelNumber = typed;
    next.tagIds = full.tags.map((t) => t.id);
    if (full.parent && full.parent.id) next.parentId = full.parent.id;
    if (full.entityType && full.entityType.id) next.entityTypeId = full.entityType.id;
    await homebox('PUT', '/entities/' + itemId, next);
  } catch (e) {
    await notify('Model not saved', `Homebox couldn't update ${offer.name}. Nothing else was done.`);
    return [];
  }
  await offerManual(itemId, typed, typed);
  return [];
}

// SAVE
if (!usable(offer.url)) { await notify('Not saved', 'There is no safe link to download for this one.'); return []; }
const fileName = `network-manual-${id}.pdf`;
try {
  const full = await homebox('GET', '/entities/' + itemId);
  if ((full.attachments || []).some((a) => String(a.title || (a.document && a.document.title) || '') === fileName)) {
    forget(itemId);
    await notify('Already saved', `${offer.name} already has this manual.`);
    return [];
  }
} catch (e) { await notify('Not saved', `Homebox couldn't be read for ${offer.name}.`); return []; }

// Follow redirects here, checking every address, so the download node never follows one by itself.
let url = offer.url;
for (let hop = 0; ; hop++) {
  let res;
  try {
    res = await http({ method: 'HEAD', url, returnFullResponse: true, disableFollowRedirect: true,
      ignoreHttpStatusErrors: true, timeout: 20000 });
  } catch (e) { break; }
  const code = res.statusCode;
  const headers = res.headers || {};
  if (code >= 300 && code < 400 && headers.location) {
    let to = String(headers.location);
    const origin = /^(https?:)\/\/[^\/?#]+/i.exec(url);
    if (to.startsWith('//')) to = origin[1] + to;
    else if (to.startsWith('/')) to = origin[0] + to;
    else if (!/^[a-z][a-z0-9+.-]*:/i.test(to)) to = url.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') + to;
    if (hop >= 4 || !usable(to)) { await notify('Not saved', 'The link redirects somewhere that isn\'t allowed.'); return []; }
    url = to; continue;
  }
  if (Number(headers['content-length'] || 0) > cfg.maxPdfMB * 1000000) {
    await notify('Not saved', `The file is over ${cfg.maxPdfMB} MB. Download it yourself and attach it in Homebox.`);
    return [];
  }
  break;
}
return [{ json: { itemId, hash: id, name: offer.name, url, fileName } }];

// Accept the download only if it really is a PDF and small enough.
const cfg = $('Settings').first().json.settings;
const job = $('Handle reply').first().json;
const item = $input.first();
let problem = '';
let data = null;
if (!item.binary || !item.binary.data) problem = "The download didn't work.";
else {
  data = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (data.length > cfg.maxPdfMB * 1000000) problem = `The file is over ${cfg.maxPdfMB} MB.`;
  else if (data.subarray(0, 5).toString('latin1') !== '%PDF-') problem = "The link didn't return a PDF.";
}
if (problem) {
  await this.helpers.httpRequest({ method: 'POST', url: cfg.notifyWebhookUrl, json: true,
    body: { title: 'Manual not saved', message: `${job.name}: ${problem}`, actions: [], url: job.url, tag: 'torke-' + job.itemId } });
  return [];
}
return [{ json: job, binary: { data: { ...item.binary.data, fileName: job.fileName, mimeType: 'application/pdf', fileExtension: 'pdf' } } }];

// Tell the phone whether Homebox took the file.
const cfg = $('Settings').first().json.settings;
const job = $('Handle reply').first().json;
const out = $input.first().json || {};
const ok = !out.error && Boolean(out.id);
if (ok) {  // n8n saves the memory when a top-level key is set, so replace the list
  const memory = $getWorkflowStaticData('global');
  const { [job.itemId]: gone, ...rest } = memory.offers || {};
  memory.offers = rest;
}
await this.helpers.httpRequest({ method: 'POST', url: cfg.notifyWebhookUrl, json: true,
  body: { title: ok ? 'Manual saved' : 'Manual not saved',
    message: ok ? `${job.name}: attached in Homebox as a Manual.`
      : `${job.name}: Homebox didn't accept the file. Open the link and attach it in Homebox yourself.`,
    actions: [], url: ok ? '' : job.url, tag: 'torke-' + job.itemId } });
return [{ json: { saved: ok, itemId: job.itemId } }];
